// ---- clamp (x86 `clamp_*`)
//
// `min(max(a, lo), hi)`, both steps vectorised: `max` into a stack chunk, then
// `min` from it into `out`. No tier check of its own; each step picks its rung.

/// Elements per stack chunk in `clamp_*`: 1 KiB for 32-bit lanes.
const CLAMP_CHUNK: usize = 256;

macro_rules! auto_clamp {
	($fn_name:ident, $max:ident, $min:ident, $Elem:ty, $nan:literal) => {
		#[doc = concat!("`out[i] = min(max(a[i], lo[i]), hi[i])`, from [`", stringify!($max), "`] then [`", stringify!($min), "`].", $nan)]
		///
		/// # Panics
		/// Length mismatch among `a`, `lo`, `hi`, `out`.
		#[inline]
		pub fn $fn_name(a: &[$Elem], lo: &[$Elem], hi: &[$Elem], out: &mut [$Elem]) {
			assert_eq!(a.len(), lo.len());
			assert_eq!(a.len(), hi.len());
			assert_eq!(out.len(), a.len());
			let mut tmp = [<$Elem>::default(); CLAMP_CHUNK];
			for (((a, lo), hi), out) in
				a.chunks(CLAMP_CHUNK).zip(lo.chunks(CLAMP_CHUNK)).zip(hi.chunks(CLAMP_CHUNK)).zip(out.chunks_mut(CLAMP_CHUNK))
			{
				let t = &mut tmp[..a.len()];
				$max(a, lo, t);
				$min(t, hi, out);
			}
		}
	};
}

auto_clamp!(
    clamp_f32,
    max_f32,
    min_f32,
    f32,
    " NaN follows `max_f32`/`min_f32` (see the module doc), so a NaN lane usually stays NaN; x86 `clamp_f32` drops it in its scalar `min` step."
);
auto_clamp!(clamp_f64, max_f64, min_f64, f64, " NaN: as [`clamp_f32`].");
auto_clamp!(clamp_i32, max_i32, min_i32, i32, "");
auto_clamp!(clamp_u32, max_u32, min_u32, u32, "");
auto_clamp!(clamp_i64, max_i64, min_i64, i64, "");
auto_clamp!(clamp_u64, max_u64, min_u64, u64, "");

